                 (getr R' 14) (getr R' 15) (getr R' 16) (getr R' 17) (Z_to_bv 64 D) (Z_to_bv 64 N) (Z_to_bv 64 0x7fff8000)
                 s5 s6 s7 s8 s9 s10 s11 (getr R' 28) (getr R' 29) (getr R' 30) (getr R' 31)
      /\ munch [(obj, obj + 2504); (sph - 96, sph)] m M' /\ wmono asegs m M' /\ mem_inv asegs M' /\ stk asegs M' lo sph
